def visit_field(field: Field, visitor: Visitor):
  args := if field.args { field.args.args.map(|arg| visit_arg(arg, visitor)) } else { None }
  new_args := if args { Args(args) } else { None }
  children := if field.children { field.children.map(|child| visit_field(child, visitor)) } else { None }
  args_didnt_change := (not new_args and not field.args) or (field.args and new_args and (field.args.args.len == new_args.args.len and field.args.args.every(|arg, index| arg == new_args.args[index])))
  fields_didnt_change := (not field.children and not children) or (field.children and children and field.children.len == children.len and field.children.every(|child, index| child == children[index]))
  if args_didnt_change and fields_didnt_change:
    return field
  return Field({name: field.name, args: new_args, children: children, error: field.error})
